#!/usr/bin/env node
/**
 * Registry generator for .claude/registry/
 *
 * Scans components, hooks, utils, and pages under overrides/app/ and writes
 * structured markdown tables that Claude Code reads instead of grepping the
 * codebase.
 *
 * Usage:
 *   node scripts/generateRegistry.mjs              # Full regeneration
 *   node scripts/generateRegistry.mjs --file=PATH  # Incremental — regenerate
 *                                                    # only the category for PATH
 *   node scripts/generateRegistry.mjs --fresh      # Full regeneration, ignoring
 *                                                    # the base/override consumer
 *                                                    # caches (forces recompute)
 */

import {readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync} from 'fs'
import {join, dirname, basename, extname, relative} from 'path'
import {fileURLToPath} from 'url'
import {execSync} from 'child_process'
import {createHash} from 'crypto'

const __dirname = dirname(fileURLToPath(import.meta.url))
const ROOT = join(__dirname, '..')
const APP = join(ROOT, 'overrides/app')
const BASE_PKG = join(ROOT, 'node_modules/@salesforce/retail-react-app')
const BASE_APP = join(BASE_PKG, 'app')
const REGISTRY = join(ROOT, '.claude/registry')
const BASE_CACHE = join(REGISTRY, '.baseCache.json')
const OVERRIDE_CACHE = join(REGISTRY, '.overrideCache.json')

if (!existsSync(REGISTRY)) mkdirSync(REGISTRY, {recursive: true})

const fileArg = process.argv.find((a) => a.startsWith('--file='))?.slice(7)
const fresh = process.argv.includes('--fresh')
const timestamp = new Date().toISOString()

/** sha1 of file content — used to detect whether a row's own source file
 *  actually changed, so its cached `consumers` count can be reused. */
function hashContent(content) {
  return createHash('sha1').update(content).digest('hex')
}

/**
 * Per-file cache of `consumers` counts for override rows in components.md and
 * hooks.md — the only two registries with a Consumers column. Keyed by repo-
 * relative path; a row's cached count is reused as long as its own file's
 * content hash hasn't changed. This intentionally does NOT track changes in
 * *other* files that reference this one — see the comment on countConsumers's
 * call sites for the tradeoff. Not used for `lastTouched`, which stays cheap
 * to recompute and self-corrects the one-commit-behind lag inherent to
 * reading git history from a pre-commit hook.
 */
function loadOverrideCache() {
  if (fresh || !existsSync(OVERRIDE_CACHE)) return {components: {}, hooks: {}}
  try {
    const cache = JSON.parse(readFileSync(OVERRIDE_CACHE, 'utf-8'))
    return {components: cache.components ?? {}, hooks: cache.hooks ?? {}}
  } catch {
    return {components: {}, hooks: {}}
  }
}

function saveOverrideCache(cache) {
  writeFileSync(OVERRIDE_CACHE, JSON.stringify(cache, null, 2))
}

const overrideCache = loadOverrideCache()

// ---------------------------------------------------------------------------
// Base template (node_modules/@salesforce/retail-react-app) — scanned so the
// registry covers inherited files as well as overrides.
// ---------------------------------------------------------------------------

const baseVersion = (() => {
  try {
    return JSON.parse(readFileSync(join(BASE_PKG, 'package.json'), 'utf-8')).version
  } catch {
    return null
  }
})()

// Bump when the shape of a cached base row changes (e.g. a new field added)
// so caches written by an older version of this script are not reused as-is.
// Bumped to 3: extractTsProps now scopes props to <ComponentName>Props instead of
// merging every *Props block, so a cache written by the previous extractor holds
// merged props for base components and must be discarded.
const BASE_CACHE_SCHEMA = 3

function loadBaseCache() {
  if (fresh || !existsSync(BASE_CACHE)) return null
  try {
    const cache = JSON.parse(readFileSync(BASE_CACHE, 'utf-8'))
    if (cache.version !== baseVersion || cache.schema !== BASE_CACHE_SCHEMA) return null
    return cache
  } catch {
    return null
  }
}

function saveBaseCache(cache) {
  writeFileSync(
    BASE_CACHE,
    JSON.stringify({version: baseVersion, schema: BASE_CACHE_SCHEMA, ...cache}, null, 2)
  )
}

/** Path under retail-react-app for display, e.g. `app/components/header/index.jsx`. */
function toBaseRelPath(abs) {
  return relative(BASE_PKG, abs).replace(/\\/g, '/')
}

/** Folder key for matching base ↔ override. Tries the path as-is and a kebab→camel variant. */
function folderVariants(folderName) {
  const camel = folderName.includes('-') ? toCamelCase(folderName) : folderName
  const kebab = folderName.replace(/([A-Z])/g, '-$1').toLowerCase().replace(/^-/, '')
  return new Set([folderName, camel, kebab])
}

