    return readFileSync(p, 'utf-8')
  } catch {
    return ''
  }
}

/** Path relative to repo root, e.g. overrides/app/components/header/index.tsx */
function toRelPath(abs) {
  return relative(ROOT, abs).replace(/\\/g, '/')
}

/**
 * Write a registry file only if its substantive content has changed. Compares
 * with the `Last updated:` line stripped so timestamp-only churn does not
 * trigger a write (and therefore does not get staged by the pre-commit hook).
 * Returns true if the file was (re)written.
 */
function writeIfChanged(path, content) {
  const stripTimestamp = (s) => s.replace(/^> Last updated:.*$/m, '')
  if (existsSync(path) && stripTimestamp(readFile(path)) === stripTimestamp(content)) {
    return false
  }
  writeFileSync(path, content)
  return true
}

function toPascalCase(str) {
  return str
    .replace(/^_+/, '')
    .split('-')
    .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
    .join('')
}

function toCamelCase(str) {
  const p = toPascalCase(str)
  return p.charAt(0).toLowerCase() + p.slice(1)
}

function findFiles(dir, exts, exclude = []) {
  const results = []
  if (!existsSync(dir)) return results
  function walk(d) {
    for (const entry of readdirSync(d, {withFileTypes: true})) {
      const full = join(d, entry.name)
      if (entry.isDirectory()) {
        if (entry.name !== 'node_modules' && !entry.name.startsWith('.')) walk(full)
      } else if (
        exts.some((e) => entry.name.endsWith(e)) &&
        !exclude.some((p) => full.includes(p))
      ) {
        results.push(full)
      }
    }
  }
  walk(dir)
  return results
}

