// Parsing helpers
// ---------------------------------------------------------------------------

/**
 * Extract the component/module-level JSDoc description from file content.
 *
 * Skips: copyright headers, JSDocs inside line-commented regions, and
 * prop-level JSDocs (those followed by an `identifier:` / `identifier?:` line).
 * Prefers an explicit `@summary` tag when present.
 * Trims to ~200 chars on a sentence boundary.
 */
function extractDescription(content, preferredName) {
  // Strip whole-line comments so commented-out JSDoc blocks are ignored.
  const stripped = content
    .split('\n')
    .map((l) => (/^\s*\/\//.test(l) ? '' : l))
    .join('\n')

  // Two passes when a name is supplied: the first only accepts the JSDoc attached to the
  // declaration the row is actually about, the second is the original "first qualifying
  // JSDoc" rule. Without the first pass any JSDoc'd top-level helper above the component
  // wins the row — footer/index.tsx's leavesTheSite and NEW_TAB_SUFFIX each did in turn,
  // and demoting them to line comments only handed the row to the next one down. Mirrors
  // extractTsProps's preferredTypeName parameter.
  for (const requireName of preferredName ? [true, false] : [false]) {
    const re = /\/\*\*([\s\S]*?)\*\//g
    let match
    while ((match = re.exec(stripped)) !== null) {
      const raw = match[1]
      if (raw.includes('Copyright') || raw.includes('SPDX-License')) continue

      // The next non-blank line after the JSDoc must be a real top-level
      // declaration. This rejects:
      //   - prop docs (next line is `name:` or `name?:`)
      //   - orphaned JSDocs whose subject is commented out (next line empty
      //     after we stripped line comments)
      const after = stripped.slice(match.index + match[0].length)
      const nextLine = after.split('\n').find((l) => l.trim().length > 0) ?? ''
      const isDeclaration =
        /^\s*(import\s|(export\s+)?(default\s+)?(async\s+)?(function|const|let|var|class|interface|type|enum)\s)/.test(
          nextLine
        )
      if (!isDeclaration) continue

      // First pass only: the declaration must be the row's own subject.
      if (requireName) {
        const declared = nextLine.match(/(?:function|const|let|var|class|interface|type|enum)\s+([A-Za-z_$][\w$]*)/)
        if (!declared || declared[1] !== preferredName) continue
      }

      const lines = raw
        .split('\n')
        .map((l) => l.replace(/^\s*\*\s?/, '').trim())
        .filter((l) => l)

      // Prefer @summary if present.
      const summaryLine = lines.find((l) => l.startsWith('@summary'))
      if (summaryLine) {
        const text = summaryLine.replace(/^@summary\s*/, '').trim()
        if (text.length > 0) return truncateAtSentence(text, 200)
      }

      const desc = lines
        .filter((l) => !l.startsWith('@'))
        .join(' ')
        .replace(/\s+/g, ' ')
        .trim()
      if (desc.length > 10) return truncateAtSentence(desc, 200)
    }
  }
  return ''
}

/**
 * Escape characters that would break a Markdown table cell.
 *
 * Union types (`'button' | 'submit'`) and prop lists routinely contain a literal `|`,
 * which Markdown reads as a column separator — the row then has more cells than the
 * header and every column after it shifts.
 */
function escapeCell(value) {
  // (?<!\\) so an already-escaped pipe is left alone. Without it, escaping text that was
  // already escaped doubles the backslash and the cell renders a literal "\\|".
  //
  // Angle brackets need the same treatment as the pipe, but only OUTSIDE a code span.
  // Bare `Array<Foo>` or `<img src>` is parsed as raw HTML by GitHub and silently dropped,
  // so it must be escaped. Inside backticks GFM already shows `<` literally and does not
  // decode entities, so escaping there would render a visible "&lt;" instead — a regression.
  // Splitting on the code-span pattern leaves odd indices (the spans) untouched. An
  // unbalanced backtick falls through to the escaping branch, which is the safe direction.
  return String(value)
    .replace(/(?<!\\)\|/g, '\\|')
    .split(/(`[^`]*`)/)
    .map((part, i) => (i % 2 ? part : part.replace(/</g, '&lt;').replace(/>/g, '&gt;')))
    .join('')
}

function truncateAtSentence(text, max) {
  if (text.length <= max) return text
  const slice = text.slice(0, max)
  const lastStop = Math.max(slice.lastIndexOf('. '), slice.lastIndexOf('; '))
  if (lastStop > max * 0.5) return slice.slice(0, lastStop + 1)
  const lastSpace = slice.lastIndexOf(' ')
  return slice.slice(0, lastSpace > 0 ? lastSpace : max) + '…'
}

/**
 * Extract top-level PropTypes prop names and whether they're required.
 * Matches only 4-space-indented lines to avoid nested shape() entries.
 * Applies to legacy `.jsx` overrides; TS components use `extractTsProps`.
 */
function extractPropTypes(content) {
  const blockMatch = content.match(/\.propTypes\s*=\s*\{([\s\S]*?)^\}/m)
  if (!blockMatch) return []

  const body = blockMatch[1]
  const props = []
  const seen = new Set()

  const re = /^ {4}(\w+)\s*:\s*PropTypes\.(\w+)([\s\S]*?)(?=\n {4}\w|\n\})/gm
  let m
  while ((m = re.exec(body)) !== null) {
    const name = m[1]
    if (seen.has(name) || name === 'children') continue
    seen.add(name)
    const typeWord = m[2]
    const rest = m[3] || ''
    const required = rest.includes('isRequired')

    const typeMap = {
      string: 'string',
      number: 'number',
      bool: 'boolean',
      func: 'function',
      array: 'array',
      object: 'object',
      node: 'node',
      element: 'element',
      shape: 'shape{…}',
      arrayOf: 'array',
      oneOf: 'enum',
      oneOfType: 'union',
      any: 'any',
    }
    const type = typeMap[typeWord] ?? typeWord
    props.push(`${name}${required ? '' : '?'}: ${type}`)
  }

  return props
}

