  // BoxProps`, `= ZimmButtonBaseProps &`, a `<T>` parameter list. Without it only the bare
  // `Props {` form matches, so an extended or intersected type resolves to nothing and the
  // preferredTypeName lookup falls into the merge-everything fallback it exists to prevent.
  // It cannot cross a newline, so `type FooProps = string` followed by an unrelated `{` on a
  // later line still correctly does not match.
  const re = /(?:type|interface)\s+(\w*Props)\s*(?:=\s*)?([^{\n]*)\{([\s\S]*?)\n\}/g
  const allBlocks = []
