    // The preferred type can also be a *union alias* — `type ZimmButtonProps = ZimmLabelButtonProps
    // | ZimmIconButtonProps` — which the block regex above cannot match, having no object-literal
    // body. Left to fall through, the merge-everything fallback flattens every variant into one row
    // and presents mutually-exclusive props as co-required: ZimmButton's row claimed both
    // `label: string` and a required `icon: ZimmIconType`, a combination the type forbids.
    const alias = new RegExp(`type\\s+${preferredTypeName}\\s*=\\s*([^;{]+);`).exec(content)
    if (alias && alias[1].includes('|')) {
      const memberNames = alias[1].split('|').map((s) => s.trim())

