      // holds only the variant-specific half. Reading that alone silently drops the shared props
      // (ZimmButton's `label` lives entirely in the base), so follow the intersection. Scoped to
      // this branch deliberately: the object-literal fast path above already produces accepted
      // rows, and resolving ancestors there too would churn unrelated entries for no fix.
      const resolveProps = ({typeName, prefix, props}, seen = new Set([typeName])) => {
        const inherited = []
        for (const [, ancestorName] of prefix.matchAll(/(\w*Props)/g)) {
          if (seen.has(ancestorName)) continue
          seen.add(ancestorName)
          const ancestor = allBlocks.find((b) => b.typeName === ancestorName)
          if (ancestor) inherited.push(...resolveProps(ancestor, seen))
        }
        return [...inherited, ...props]
