  // Fallback: merge all blocks, deduplicating by prop name (first occurrence wins).
  const seen = new Set()
  const props = []
  for (const {props: blockProps} of allBlocks) {
    for (const p of blockProps) {
      const name = p.split(/[?:]/)[0]
      if (!seen.has(name)) {
        seen.add(name)
        props.push(p)
      }
