/**
 * Extract named exports from a utility file.
 */
function extractExports(content) {
  const matches = [
    ...content.matchAll(/^export\s+(?:const|function|async\s+function)\s+(\w+)/gm),
  ]
  return [...new Set(matches.map((m) => m[1]).filter((n) => !n.startsWith('_')))]
}

/**
 * Last commit date (YYYY-MM-DD) for a tracked file. Returns '—' for paths
 * inside node_modules, untracked files, or when skipped in incremental mode.
 */
function getLastTouched(relPath, incremental) {
  if (incremental || !relPath || relPath.startsWith('node_modules/')) return '—'
  try {
    const out = execSync(`git log -1 --format=%cs -- "${relPath}"`, {
      encoding: 'utf-8',
      cwd: ROOT,
      timeout: 3000,
      stdio: ['ignore', 'pipe', 'ignore'],
    })
    return out.trim() || '—'
  } catch {
    return '—'
  }
}

/**
 * Count non-test files that import a given name (hook or util filename stem).
 * Skipped in incremental mode to keep the PostToolUse hook fast.
 */
function countConsumers(stem, incremental) {
  if (incremental) return '—'
  try {
    const count = execSync(
      `grep -rl "${stem}" "${APP}" --include="*.js" --include="*.jsx" --include="*.ts" --include="*.tsx" 2>/dev/null | grep -v "\\.test\\." | grep -v "${stem}\\." | wc -l`,
      {encoding: 'utf-8', timeout: 8000}
    )
    return parseInt(count.trim(), 10) || 0
  } catch {
    return '—'
  }
}

// ---------------------------------------------------------------------------
// Base template scanners — read once, cached by base package version.
// Each returns rows shaped like override rows so the generators can merge.
// ---------------------------------------------------------------------------

function scanBaseComponents() {
  if (!existsSync(BASE_APP)) return []
  const dir = join(BASE_APP, 'components')
  const files = findFiles(dir, ['.jsx', '.tsx'], ['.test.', '.stories.', '/shared/ui']).filter(
    (f) => basename(f).startsWith('index.')
  )
  return files.map((file) => {
    const folder = basename(dirname(file))
    const content = readFile(file)
    const props = file.endsWith('.tsx') ? extractTsProps(content, `${toPascalCase(folder)}Props`) : extractPropTypes(content)
    return {
      key: folder,
      name: toPascalCase(folder),
      path: toBaseRelPath(file),
      props: props.length ? props.join(', ') : '—',
      desc: extractDescription(content, toPascalCase(folder)) || '—',
      // Computed once per base-package version (this whole scan is skipped on
      // a cache hit — see loadBaseCache) rather than on every registry regen.
      consumers: countConsumers(folder, false),
    }
  })
}

function scanBaseHooks() {
  if (!existsSync(BASE_APP)) return []
  const dir = join(BASE_APP, 'hooks')
  const files = findFiles(dir, ['.js', '.ts'], ['.test.', '.stories.']).filter((f) => {
    const name = basename(f)
    const rel = relative(dir, f).replace(/\\/g, '/')
    const parts = rel.split('/')
    const isHookName = (n) => /^use[-A-Z]/.test(n)
    if (parts.length === 1 && isHookName(name.replace(/\.(ts|js)$/, ''))) return true
    if (parts.length === 2 && /^index\.(ts|js)$/.test(name) && isHookName(parts[0])) return true
    return false
  })
  const seen = new Set()
  return files
    .map((file) => {
      const name = basename(file)
      const parentDir = basename(dirname(file))
      const stem = /^index\.(ts|js)$/.test(name) ? parentDir : basename(file, extname(file))
      const hookName = stem.includes('-') ? toCamelCase(stem) : stem
      const content = readFile(file)
      return {
        key: stem,
        name: hookName,
        path: toBaseRelPath(file),
        desc: extractDescription(content, hookName) || '—',
        consumers: countConsumers(stem, false),
      }
    })
    .filter((r) => {
      if (seen.has(r.name)) return false
      seen.add(r.name)
      return true
    })
}

function scanBaseUtils() {
  if (!existsSync(BASE_APP)) return []
  const dir = join(BASE_APP, 'utils')
  const files = findFiles(dir, ['.js', '.ts'], ['.test.', '.stories.', 'test-utils']).filter(
    (f) => !basename(f).startsWith('index')
  )
  return files.map((file) => {
    const name = basename(file, extname(file))
    const content = readFile(file)
    const exports = extractExports(content)
    return {
      key: name,
      name,
      path: toBaseRelPath(file),
      exports: exports.length ? exports.join(', ') : '—',
      desc: extractDescription(content, name) || '—',
    }
  })
}

