    const count = execSync(
      `grep -rl "${stem}" "${APP}" --include="*.js" --include="*.jsx" --include="*.ts" --include="*.tsx" 2>/dev/null | grep -v "\\.test\\." | grep -v "${stem}\\." | wc -l`,
