function scanBaseComponents() {
  if (!existsSync(BASE_APP)) return []
  const dir = join(BASE_APP, 'components')
  const files = findFiles(dir, ['.jsx', '.tsx'], ['.test.', '.stories.', '/shared/ui']).filter(
    (f) => basename(f).startsWith('index.')
  )
  return files.map((file) => {
    const folder = basename(dirname(file))
    const content = readFile(file)
    const props = file.endsWith('.tsx') ? extractTsProps(content, `${toPascalCase(folder)}Props`) : extractPropTypes(content)
    return {
      key: folder,
      name: toPascalCase(folder),
      path: toBaseRelPath(file),
      props: props.length ? props.join(', ') : '—',
      desc: extractDescription(content, toPascalCase(folder)) || '—',
      // Computed once per base-package version (this whole scan is skipped on
      // a cache hit — see loadBaseCache) rather than on every registry regen.
      consumers: countConsumers(folder, false),
    }
  })
}

function scanBaseHooks() {
  if (!existsSync(BASE_APP)) return []
  const dir = join(BASE_APP, 'hooks')
  const files = findFiles(dir, ['.js', '.ts'], ['.test.', '.stories.']).filter((f) => {
    const name = basename(f)
    const rel = relative(dir, f).replace(/\\/g, '/')
    const parts = rel.split('/')
    const isHookName = (n) => /^use[-A-Z]/.test(n)
    if (parts.length === 1 && isHookName(name.replace(/\.(ts|js)$/, ''))) return true
    if (parts.length === 2 && /^index\.(ts|js)$/.test(name) && isHookName(parts[0])) return true
    return false
  })
  const seen = new Set()
  return files
    .map((file) => {
      const name = basename(file)
      const parentDir = basename(dirname(file))
      const stem = /^index\.(ts|js)$/.test(name) ? parentDir : basename(file, extname(file))
      const hookName = stem.includes('-') ? toCamelCase(stem) : stem
      const content = readFile(file)
      return {
        key: stem,
        name: hookName,
        path: toBaseRelPath(file),
        desc: extractDescription(content, hookName) || '—',
        consumers: countConsumers(stem, false),
      }
    })
    .filter((r) => {
      if (seen.has(r.name)) return false
      seen.add(r.name)
      return true
    })
}

