function generatePages() {
  const pagesDir = join(APP, 'pages')
  const overrideEntries = existsSync(pagesDir)
    ? readdirSync(pagesDir, {withFileTypes: true}).filter((e) => e.isDirectory())
    : []

  const baseByKey = new Map(baseScan.pages.map((b) => [b.key, b]))

  const overrideRows = overrideEntries.map((entry) => {
    const dir = entry.name
    const tsx = join(pagesDir, dir, 'index.tsx')
    const jsx = join(pagesDir, dir, 'index.jsx')
    const abs = existsSync(tsx) ? tsx : existsSync(jsx) ? jsx : tsx
    const baseMatch = [...folderVariants(dir)].map((v) => baseByKey.get(v)).find(Boolean)
    if (baseMatch) baseByKey.delete(baseMatch.key)
    const relPath = toRelPath(abs)
    return {
      name: toPascalCase(dir),
      origin: baseMatch ? 'Override' : 'Custom',
      path: relPath,
      squad: getSquad(`app/pages/${dir}/`),
      tier: getTier(`app/pages/${dir}/`),
      lastTouched: getLastTouched(relPath, false),
    }
  })

  const baseRows = [...baseByKey.values()].map((b) => ({
    name: b.name,
    origin: 'Base',
    path: b.path,
    squad: getSquad(`app/pages/${b.key}/`),
    tier: getTier(`app/pages/${b.key}/`),
    lastTouched: '—',
  }))

  const rows = [...overrideRows, ...baseRows].sort((a, b) => a.name.localeCompare(b.name))

  const counts = rows.reduce(
    (acc, r) => ((acc[r.origin] = (acc[r.origin] ?? 0) + 1), acc),
    {}
  )

  const out =
    `# Page Registry\n` +
    `> Generated by \`node scripts/generateRegistry.mjs\` — do not edit manually.\n` +
    `> Last updated: ${timestamp}\n` +
    `> Base: \`@salesforce/retail-react-app@${baseVersion ?? 'unknown'}\`\n\n` +
    `| Page | Origin | Path | Squad | Tier | Last touched |\n` +
    `|------|--------|------|-------|------|--------------|\n` +
    rows
      .map(
        (r) =>
          `| ${r.name} | ${r.origin} | \`${r.path}\` | ${r.squad} | ${r.tier} | ${r.lastTouched} |`
      )
      .join('\n') +
    '\n'

  writeIfChanged(join(REGISTRY, 'pages.md'), out)
  console.log(
    `  pages.md       — ${rows.length} entries (Override: ${counts.Override ?? 0}, Custom: ${counts.Custom ?? 0}, Base: ${counts.Base ?? 0})`
  )
}

/**
 * Parse a routes file into `{routePath, component, pagePath, squad, tier}`
 * rows. Local-only — does not follow spreads.
 */
function parseRoutesFile(filePath) {
  const content = readFile(filePath)

  const nameToFolder = new Map()
  for (const m of content.matchAll(
    /const\s+(\w+)\s*=\s*loadable\s*\(\s*\(\s*\)\s*=>\s*import\(\s*['"]([^'"]+)['"]/g
  )) {
    const folder = m[2].replace(/^\.\//, '').replace(/^pages\//, '')
    nameToFolder.set(m[1], folder)
  }

  const rows = []
  for (const m of content.matchAll(
    /\{\s*path:\s*['"]([^'"]+)['"][^}]*?component:\s*(\w+)/g
  )) {
    const compName = m[2]
    const folder = nameToFolder.get(compName)
    const topFolder = folder ? folder.split('/')[0] : null
    rows.push({
      routePath: m[1],
      component: compName,
      pagePath: folder ? `app/pages/${folder}/` : '—',
      squad: topFolder ? getSquad(`app/pages/${topFolder}/`) : 'Shared',
      tier: topFolder ? getTier(`app/pages/${topFolder}/`) : '4 — Feature-local',
    })
  }
  return {rows, content}
}

function generateRoutes() {
  const overrideRoutes = ['routes.tsx', 'routes.jsx'].map((f) => join(APP, f)).find(existsSync)
  const baseRoutes = ['routes.jsx', 'routes.tsx'].map((f) => join(BASE_APP, f)).find(existsSync)
  const primary = overrideRoutes ?? baseRoutes
  if (!primary) {
    writeIfChanged(
      join(REGISTRY, 'routes.md'),
      `# Route Registry\n> No routes file found.\n`
    )
    console.log(`  routes.md      — 0 entries`)
    return
  }

  const {rows: localRows, content: primaryContent} = parseRoutesFile(primary)
  const localTagged = localRows.map((r) => ({...r, source: overrideRoutes ? 'Override' : 'Base'}))

  // Detect spread of base routes: `import {routes as Alias} from '@salesforce/retail-react-app/app/routes'`
  // (or no alias) followed by `...Alias` inside the routes array.
  let inheritedRows = []
  if (overrideRoutes && baseRoutes) {
    const aliasMatch = primaryContent.match(
      /import\s*\{([^}]*\broutes\b[^}]*)\}\s*from\s*['"]@salesforce\/retail-react-app\/app\/routes['"]/
    )
    if (aliasMatch) {
      const aliasGroup = aliasMatch[1]
      const renamed = aliasGroup.match(/\broutes\s+as\s+(\w+)/)
      const alias = renamed ? renamed[1] : 'routes'
      if (new RegExp(`\\.\\.\\.${alias}\\b`).test(primaryContent)) {
        const {rows} = parseRoutesFile(baseRoutes)
        inheritedRows = rows.map((r) => ({...r, source: 'Inherited'}))
      }
    }
  }

  // Local routes declared before `..._routes` shadow inherited ones at the same URL.
  // Drop the inherited duplicate so the table reflects runtime behaviour.
  const localUrls = new Set(localTagged.map((r) => r.routePath))
  const all = [...localTagged, ...inheritedRows.filter((r) => !localUrls.has(r.routePath))].sort(
    (a, b) => a.routePath.localeCompare(b.routePath)
  )

  const counts = all.reduce(
    (acc, r) => ((acc[r.source] = (acc[r.source] ?? 0) + 1), acc),
    {}
  )

  const filePath = overrideRoutes ? toRelPath(primary) : toBaseRelPath(primary)
  const out =
    `# Route Registry\n` +
    `> Generated by \`node scripts/generateRegistry.mjs\` — do not edit manually.\n` +
    `> Last updated: ${timestamp}\n` +
    `> Source: \`${filePath}\`${inheritedRows.length ? ` (+ inherited base routes)` : ''}\n` +
    `> Base: \`@salesforce/retail-react-app@${baseVersion ?? 'unknown'}\`\n\n` +
    `| URL | Component | Page folder | Source | Squad | Tier |\n` +
    `|-----|-----------|-------------|--------|-------|------|\n` +
    all
      .map(
        (r) =>
          `| \`${r.routePath}\` | ${r.component} | \`${r.pagePath}\` | ${r.source} | ${r.squad} | ${r.tier} |`
      )
      .join('\n') +
    '\n'

  writeIfChanged(join(REGISTRY, 'routes.md'), out)
  const breakdown = Object.entries(counts)
    .map(([k, v]) => `${k}: ${v}`)
    .join(', ')
  console.log(`  routes.md      — ${all.length} entries (${breakdown})`)
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

if (fileArg) {
  const rel = fileArg.replace(/\\/g, '/')
  if (rel.includes('/components/')) {
    process.stdout.write('Updating components registry... ')
    generateComponents(true)
  } else if (rel.includes('/hooks/')) {
    process.stdout.write('Updating hooks registry... ')
    generateHooks(true)
  } else if (rel.includes('/utils/')) {
    process.stdout.write('Updating utils registry... ')
    generateUtils(true)
  } else if (rel.includes('/pages/')) {
    process.stdout.write('Updating pages registry... ')
    generatePages()
  } else if (/\/routes\.(tsx|jsx|ts|js)$/.test(rel)) {
    process.stdout.write('Updating routes registry... ')
    generateRoutes()
  } else {
    process.exit(0)
  }
} else {
  console.log('Generating Claude Code registry...')
  generateComponents(false)
  generateHooks(false)
  generateUtils(false)
  generatePages()
  generateRoutes()
  console.log('Done.')
}

